# ---- Defaults (overridable via docker run -e ...) ----
: "${NOX_NO_INTERNET_SERVERS:=0}"   # 1 = no internet (LAN ok), 0 = allow internet

: "${NOX_LOBBY_HOST:=nox.nwca.xyz}"
: "${NOX_LOBBY_PORT:=8088}"
: "${NOX_LOBBY_PATH:=/api/v0/games/list}"

: "${NOX_LOBBY_CONNECT_TIMEOUT:=2000}"  # ms
: "${NOX_SERVER_CACHE_TTL:=30}"         # seconds (min 30)

: "${NOX_BAD_SERVER_IPS:=127.1.1.1,127.1.1.2}"
: "${NOX_BAD_SERVER_NAMES:=VeryBadServerName1,VeryBadServerName2}"

# Register game on lobby
: "${NOX_LOBBY_REGISTER_ENABLE:=0}"
: "${NOX_LOBBY_REGISTER_PERIOD:=20}"
: "${NOX_LOBBY_REGISTER_PATH:=/api/v0/games/register}"
: "${NOX_SERVER_MODE:=ctf}"
: "${NOX_SERVER_VERS:=1.2}"

# UPNP port mapping
: "${NOX_UPNP_ENABLE:=0}"
: "${NOX_UPNP_DEBUG:=0}"
: "${NOX_UPNP_PORT:=18590}"
: "${NOX_UPNP_PROTO:=udp}"
: "${NOX_UPNP_TIMEOUT_MS:=2000}"

export NOX_NO_INTERNET_SERVERS \
       NOX_LOBBY_HOST NOX_LOBBY_PORT NOX_LOBBY_PATH \
       NOX_LOBBY_CONNECT_TIMEOUT NOX_SERVER_CACHE_TTL \
       NOX_BAD_SERVER_IPS NOX_BAD_SERVER_NAMES \
       NOX_LOBBY_REGISTER_ENABLE NOX_LOBBY_REGISTER_PERIOD NOX_LOBBY_REGISTER_PATH \
       NOX_SERVER_MODE NOX_SERVER_VERS \
       NOX_UPNP_ENABLE NOX_UPNP_DEBUG NOX_UPNP_PORT NOX_UPNP_PROTO NOX_UPNP_TIMEOUT_MS

# Defaults (overridable via `docker run -e ...`)
: "${NOX_CONTROL_SERVER:=1}"
: "${NOX_CONTROL_SERVER_PASSWORD:=secret}"

: "${NOX_CONTROL_SERVER_BIND:=127.0.0.1}"
: "${NOX_CONTROL_SERVER_PORT:=2323}"

: "${NOX_CAPTURE_INPUT:=0}"     # optional defaults
: "${NOX_NET_LOG:=0}"
: "${NOX_WSA_LOG:=0}"
: "${NOX_PACKET_LOG:=0}"

: "${NOX_CTRL_SLEEP_SCALE:=3}"
: "${NOX_CONTROL_SERVER_BOOT:=sleep 10000; macro server;}"
: "${NOX_SKIP_INTRO_MOVIES:=1}"

export NOX_CONTROL_SERVER \
       NOX_CONTROL_SERVER_PASSWORD \
       NOX_CONTROL_SERVER_BIND \
       NOX_CONTROL_SERVER_PORT \
       NOX_CAPTURE_INPUT \
       NOX_NET_LOG \
       NOX_WSA_LOG \
       NOX_PACKET_LOG \
       NOX_CTRL_SLEEP_SCALE \
       NOX_CONTROL_SERVER_BOOT \
       NOX_SKIP_INTRO_MOVIES

uname -m
file "$GAMEDIR/$BINARY.${RUN_ARCH}"
readelf -h "$GAMEDIR/$BINARY.${RUN_ARCH}" | sed -n '1,25p'
readelf -l "$GAMEDIR/$BINARY.${RUN_ARCH}" | grep -i interpreter || true

echo "which libs"
/lib/ld-linux.so.2 --list /opt/nox-decomp/noxd.i386

# Defaults, overridable via `docker run -e ...`
: "${ALSOFT_DRIVERS:=null}"
: "${LIBGL_ALWAYS_SOFTWARE:=1}"
: "${SDL_VIDEODRIVER:=x11}"

export ALSOFT_DRIVERS LIBGL_ALWAYS_SOFTWARE SDL_VIDEODRIVER

